/**
 * Utility to inject accurate Duration metadata into WebM files generated by browser MediaRecorder.
 * MediaRecorder streams chunks live without knowing the final duration, so it omits the EBML
 * Duration tag (0x4489) inside the Info element. Mobile players (Android, iOS, WhatsApp)
 * consequently assume the video is 3 seconds or unseekable.
 *
 * This utility parses the EBML tree, locates or inserts the Duration tag, and produces a
 * patched Blob with the exact total duration in milliseconds.
 */

function readVint(
  buffer: Uint8Array,
  start: number
): { length: number; value: number } | null {
  if (start >= buffer.length) return null;
  const firstByte = buffer[start];
  let length = 0;
  let mask = 0x80;

  for (let i = 0; i < 8; i++) {
    if ((firstByte & mask) !== 0) {
      length = i + 1;
      break;
    }
    mask >>= 1;
  }

  if (length === 0 || start + length > buffer.length) return null;

  let value = firstByte & (mask - 1);
  for (let i = 1; i < length; i++) {
    value = (value << 8) | buffer[start + i];
  }

  return { length, value };
}

function writeVint(value: number, minLength: number = 1): Uint8Array {
  let length = 1;
  let maxVal = (1 << 7) - 2;

  while (length < 8 && value > maxVal) {
    length++;
    maxVal = (1 << (7 * length)) - 2;
  }

  length = Math.max(length, minLength);
  const result = new Uint8Array(length);
  const marker = 1 << (8 - length);

  let temp = value;
  for (let i = length - 1; i >= 0; i--) {
    result[i] = temp & 0xff;
    temp >>= 8;
  }
  result[0] |= marker;
  return result;
}

export async function fixWebmDuration(blob: Blob, durationMs: number): Promise<Blob> {
  try {
    const arrayBuffer = await blob.arrayBuffer();
    const buffer = new Uint8Array(arrayBuffer);

    // 1. Verify EBML Header (0x1A, 0x45, 0xDF, 0xA3)
    if (
      buffer[0] !== 0x1a ||
      buffer[1] !== 0x45 ||
      buffer[2] !== 0xdf ||
      buffer[3] !== 0xa3
    ) {
      // Not a standard WebM, return original blob
      return blob;
    }

    let pos = 0;

    // Skip EBML Header element
    pos += 4;
    const ebmlHeaderLen = readVint(buffer, pos);
    if (!ebmlHeaderLen) return blob;
    pos += ebmlHeaderLen.length + ebmlHeaderLen.value;

    // Find Segment element (0x18, 0x53, 0x80, 0x67)
    let segmentPos = -1;
    for (let i = pos; i < Math.min(pos + 128, buffer.length - 4); i++) {
      if (
        buffer[i] === 0x18 &&
        buffer[i + 1] === 0x53 &&
        buffer[i + 2] === 0x80 &&
        buffer[i + 3] === 0x67
      ) {
        segmentPos = i;
        break;
      }
    }

    if (segmentPos === -1) return blob;

    pos = segmentPos + 4;
    const segmentLen = readVint(buffer, pos);
    if (!segmentLen) return blob;
    pos += segmentLen.length;

    // Find Info element (0x15, 0x49, 0xA9, 0x66) inside Segment
    let infoPos = -1;
    const searchLimit = Math.min(pos + 4096, buffer.length - 4);
    for (let i = pos; i < searchLimit; i++) {
      if (
        buffer[i] === 0x15 &&
        buffer[i + 1] === 0x49 &&
        buffer[i + 2] === 0xa9 &&
        buffer[i + 3] === 0x66
      ) {
        infoPos = i;
        break;
      }
    }

    if (infoPos === -1) return blob;

    const infoLenPos = infoPos + 4;
    const infoLen = readVint(buffer, infoLenPos);
    if (!infoLen) return blob;

    const infoDataStart = infoLenPos + infoLen.length;
    const infoDataEnd = infoDataStart + infoLen.value;

    // Search for existing Duration tag (0x44, 0x89) inside Info
    let durationTagPos = -1;
    let durationDataPos = -1;
    let durationDataLen = 0;

    let scanPos = infoDataStart;
    while (scanPos < infoDataEnd) {
      if (buffer[scanPos] === 0x44 && buffer[scanPos + 1] === 0x89) {
        durationTagPos = scanPos;
        const tagLen = readVint(buffer, scanPos + 2);
        if (tagLen) {
          durationDataPos = scanPos + 2 + tagLen.length;
          durationDataLen = tagLen.value;
        }
        break;
      }
      // Skip current sub-element
      const id = readVint(buffer, scanPos);
      if (!id) break;
      const size = readVint(buffer, scanPos + id.length);
      if (!size) break;
      scanPos += id.length + size.length + size.value;
    }

    if (durationTagPos !== -1 && durationDataPos !== -1) {
      // Overwrite existing duration in-place
      const view = new DataView(arrayBuffer, durationDataPos, durationDataLen);
      if (durationDataLen === 4) {
        view.setFloat32(0, durationMs, false); // big-endian
      } else if (durationDataLen === 8) {
        view.setFloat64(0, durationMs, false); // big-endian
      }
      return new Blob([buffer], { type: blob.type });
    }

    // If Duration tag does not exist inside Info, insert it!
    // Duration tag: ID 0x4489, VINT size 8 (0x88), 8 bytes Float64
    const durationTagBuffer = new Uint8Array(11);
    durationTagBuffer[0] = 0x44;
    durationTagBuffer[1] = 0x89;
    durationTagBuffer[2] = 0x88; // 8 bytes Float64
    const view = new DataView(durationTagBuffer.buffer, 3, 8);
    view.setFloat64(0, durationMs, false);

    // Update Info element length
    const newInfoLenVal = infoLen.value + 11;
    const newInfoLenBytes = writeVint(newInfoLenVal, infoLen.length);

    // Construct the new buffer by inserting Duration tag right at infoDataEnd
    const prefix = buffer.subarray(0, infoLenPos);
    const infoData = buffer.subarray(infoDataStart, infoDataEnd);
    const suffix = buffer.subarray(infoDataEnd);

    const merged = new Uint8Array(
      prefix.length + newInfoLenBytes.length + infoData.length + durationTagBuffer.length + suffix.length
    );

    let offset = 0;
    merged.set(prefix, offset);
    offset += prefix.length;

    merged.set(newInfoLenBytes, offset);
    offset += newInfoLenBytes.length;

    merged.set(infoData, offset);
    offset += infoData.length;

    merged.set(durationTagBuffer, offset);
    offset += durationTagBuffer.length;

    merged.set(suffix, offset);

    // If Segment length is not unknown (0x01FFFFFFFFFFFFFF), update it
    if (segmentLen.value < 0x00ffffffffffff) {
      const segLenPos = segmentPos + 4;
      const newSegLenVal = segmentLen.value + 11 + (newInfoLenBytes.length - infoLen.length);
      const newSegLenBytes = writeVint(newSegLenVal, segmentLen.length);
      merged.set(newSegLenBytes, segLenPos);
    }

    return new Blob([merged], { type: blob.type || 'video/webm' });
  } catch (err) {
    console.warn('Failed to patch WebM duration header, returning original blob:', err);
    return blob;
  }
}
